arguments.command:
cd /tmp/sv-76a83c25a6094c6aa2dfdb3c872a020b/moderate-msbuild-properties && dotnet package list --format json 2>/dev/null | python3 -c "
import sys, json
data = json.load(sys.stdin)
json.dump(data, open('after-cpm-packages.json','w'), indent=2)
for p in data['projects']:
    name = p['path'].split('/')[-1]
    for fw in p['frameworks']:
        for pkg in fw['topLevelPackages']:
            print(f'{name}: {pkg[\"id\"]} {pkg[\"resolvedVersion\"]}')
"

